// Cyrus per-game adapter contract (MASTER-PLAN 4.10). The engine core (lib/cyrus/engine-core) is game-agnostic;
// everything it needs to know about one game comes through this interface. Pure types + data, client-safe.
// Adapter #1 is lib/cyrus/adapters/minecraft.ts. A new game = one new adapter file + a row in adapters/index.ts.
import type { ArtifactRoute, AssetKind } from "../engine-core/spec";
import type { AssetProfile } from "./asset-profile";

/**
 * How far a game's support really goes. Never claim more than ran:
 * planned = nothing built; template = canned preview code only (no compile); beta = real AI build + compile + scan;
 * stable = beta plus boot and functional tests on every build.
 */
export type AdapterMaturity = "planned" | "template" | "beta" | "stable";

/** available = Cyrus produces it today; planned = on the roadmap, not built; unsupported = the game cannot use it. */
export type RouteAvailability = "available" | "planned" | "unsupported";

export type ArtifactType = {
  route: ArtifactRoute;
  availability: RouteAvailability;
  /** File form of the artifact ("jar", "zip", "dll"...). */
  packaging: string;
  side: "server" | "client" | "both";
  /** Customer-voice explanation, shown by the router. */
  note: string;
};

/** A version as the engine core sees it (an adapter maps its own registry rows to this). */
export type AdapterVersion = {
  id: string;
  status: "supported" | "preview" | "legacy" | "blocked";
  buildable: boolean;
  /** Game-specific capability flags, e.g. "dialogApi". The core only passes them through to router rules. */
  capabilities: readonly string[];
};

export type ToolchainProfile = {
  language: string;
  /** How a build is compiled (or "none" when only linted). */
  compiler: string;
  /** Compiler/runtime release per version, or null when the version is not buildable. */
  releaseFor: (version: string) => string | null;
  /** Where the deny-list / safety scan lives (repo path), so a build record can cite it. */
  scanner: string;
};

export type AssetDelivery = {
  supported: boolean;
  /** How asset files reach players. */
  via: "server-pushed-pack" | "client-zip" | "client-mod" | "server-files" | "none";
  /** available = delivery works today; planned = designed, not built. */
  availability: "available" | "planned" | "none";
  note: string;
};

export type InstallRules = {
  side: "server" | "client" | "both";
  serverPath: string;
  needsRestart: boolean;
  hotReload: boolean;
  summary: string;
};

export type TestLane = {
  compile: boolean;
  scan: boolean;
  /** Boot the real game server with the artifact. */
  boot: "none" | "planned" | "available";
  /** Scripted functional checks (bot, RCON...). */
  functional: "none" | "planned" | "available";
  notes: string;
};

/**
 * One deterministic routing rule. The core router matches `keywords` (lower-case regex sources) against the spec text
 * and prompt; on a match it adds `route` and the honest limit, and checks `requiresCapability` on the target version.
 */
export type RouteRule = {
  id: string;
  keywords: string[];
  /** Asset kinds that trigger this rule without any keyword. */
  assetKinds?: AssetKind[];
  route?: ArtifactRoute;
  requiresCapability?: { capability: string; message: string; /** true = a missing capability is a downgrade (warn), not a block */ downgrade?: boolean;
    /** a weaker capability that still serves the rule (e.g. 1.21.1 legacy custom model data): present = a warn with this message instead of the block */
    fallback?: { capability: string; message: string } };
  /** Build-asset kinds (lib/cyrus/assets/kinds.ts) this rule asks for, when they differ from the spec kinds in assetKinds. */
  buildAssetKinds?: string[];
  /** Shown whenever the rule matches (a fact the user must know: a restart, a client-side limit...). */
  limit?: { severity: "info" | "warn"; message: string };
};

export interface GameAdapter {
  game: string;
  name: string;
  maturity: AdapterMaturity;
  artifacts: readonly ArtifactType[];
  /** The route a request lands on when nothing else is asked for. */
  defaultRoute: ArtifactRoute;
  toolchain: ToolchainProfile;
  /** Where the model's API knowledge for this game lives (two systems exist today, see G-gaps.md (b)). */
  knowledge: { kind: "version-sheets" | "knowledge-pack" | "none"; ref: string };
  versions: {
    list: () => readonly AdapterVersion[];
    get: (id: string) => AdapterVersion | null;
    hasCapability: (id: string, capability: string) => boolean;
  };
  assetDelivery: Readonly<Record<AssetKind, AssetDelivery>>;
  install: InstallRules;
  testLane: TestLane;
  routeRules: readonly RouteRule[];
  /** 3D/texture asset facts (formats, channels, delivery, worker class, legal). Optional: a game without one is text/code only. */
  assetProfile?: AssetProfile;
}
// Asset profile: what ONE game's adapter declares about 3D/texture assets (MULTIGAME research H-3d-games.md, section 3).
// Interfaces + a validator only. Nothing here changes behaviour; Minecraft is the first filled-in profile, every
// other game declares its own when its adapter is written. Pure, client-safe, no Nxeon imports.
import type { AdapterMaturity } from "./types";
import type { MotionCapability } from "../motion/caps";

/** How custom assets reach players. Only the first and the two workshop forms need no player action. */
export const DELIVERY_STRATEGIES = ["server-streamed", "workshop-user-publishes", "workshop-platform-publishes", "client-manual", "none"] as const;
export type DeliveryStrategy = (typeof DELIVERY_STRATEGIES)[number];

/** Which kind of worker a job needs. linux-cpu = node-2 style builds; windows-tools = Windows-only game tools; gpu = image/3D models. */
export const WORKER_CLASSES = ["linux-cpu", "windows-tools", "gpu"] as const;
export type WorkerClass = (typeof WORKER_CLASSES)[number];

/** none = nothing from the game needed; user-supplied = the user brings templates/base files; platform-licensed = Nxeon holds a licence. */
export const REQUIRED_GAME_FILES = ["none", "user-supplied", "platform-licensed"] as const;
export type RequiredGameFiles = (typeof REQUIRED_GAME_FILES)[number];

/** Channel roles of a texture set. Stored as separate lossless layers; packed into engine channels only at export. */
export const CHANNEL_ROLES = ["albedo", "normal", "roughness", "metallic", "ao", "emissive", "height", "opacity", "mask"] as const;
export type ChannelRole = (typeof CHANNEL_ROLES)[number];

export type ColorSpace = "srgb" | "linear";
export type NormalConvention = "opengl" | "directx" | "none";
export type TextureCompression = "png" | "bc1" | "bc3" | "bc5" | "bc7" | "ktx2";
export type EngineFamily = "minecraft-java" | "unreal" | "unity" | "source" | "rage" | "creation" | "hytale" | "other";

/** Where a role lands in the game's packed texture: a file name pattern and the channel(s) of it. */
export type ChannelTarget = { file: string; channels: "rgb" | "rgba" | "r" | "g" | "b" | "a" };

/** What the game owner's published terms say about hosted modding. `reviewed` is false until a human read the page. */
export type LegalPolicy = {
  policyUrl: string | null;
  /** true / false only when a reviewer read the source; otherwise "unknown" (the honest default). */
  commercialOk: boolean | "unknown";
  aiOk: boolean | "unknown";
  /** A game's own assets are never redistributed, so this is the literal false. */
  redistributeBase: false;
  monetisationRule?: string;
  attestationRequired: boolean;
  /** ISO date the policy page was last read, or null. */
  retrievedAt: string | null;
  reviewed: boolean;
};

export type AssetProfile = {
  game: string;
  engineFamily: EngineFamily;
  meshFormats: readonly string[];
  textureFormats: readonly string[];
  compression: readonly TextureCompression[];
  channelMap: Readonly<Partial<Record<ChannelRole, ChannelTarget>>>;
  normalConvention: NormalConvention;
  colorSpace: Readonly<Partial<Record<ChannelRole, ColorSpace>>>;
  /** Largest texture edge in pixels the game/adapter accepts. */
  maxTextureRes: number;
  /** AI mesh (meshgen, Model Studio L4) targets. Absent = the game takes no meshgen meshes (Minecraft: no meshes). */
  meshBudget?: AssetMeshBudget;
  /** reuse-template = the user's UV layout is kept; new = Cyrus may unwrap; none = the game has no UVs to manage. */
  uvRules: "reuse-template" | "new" | "none";
  skeletonPolicy: "reuse" | "own" | "none" | "forbidden";
  packaging: string;
  delivery: DeliveryStrategy;
  workerClass: WorkerClass;
  requiredGameFiles: RequiredGameFiles;
  legal: LegalPolicy;
  validators: readonly string[];
  previewShader: string;
  maturity: AdapterMaturity;
  /** optional catalog hints (asset catalog v2); see CatalogFitHints */
  catalog?: CatalogFitHints;
  /** what the game's motion lowering supports (the motion core's adapter contract, lib/cyrus/motion). Absent = no motion yet. */
  motion?: MotionCapability;
};

/**
 * What the asset CATALOG needs to judge "does this library asset fit this game" (lib/cyrus/library/v2/fit.ts).
 * Optional: a game without hints gets no fit row (unknown), never an assumed "good".
 *   accepts: per catalog kind, native = used as is / convert = Cyrus has a working converter / none = cannot use it.
 */
export type CatalogFitHints = {
  accepts: Readonly<Partial<Record<"model" | "texture-set" | "texture" | "sprite" | "hdri" | "decal" | "sound" | "music" | "flipbook" | "particle-texture" | "animation-clip" | "animated-model" | "motion-preset" | "effect-preset", "native" | "convert" | "none">>>;
  /** why a kind is "none" (shown to the model and the owner) */
  noneReasons?: Readonly<Partial<Record<string, string>>>;
  /** styles that look at home in the game (pixel-art for Minecraft); other styles fit "ok" at best */
  styleAffinity: readonly string[];
  /** triangle budgets per use (a single prop, a character, a vehicle); absent = not a mesh game */
  triBudget?: Readonly<{ prop: number; character: number; vehicle: number }>;
  /** largest texture edge before a downscale is needed, and the smallest that still reads well */
  textureRes?: Readonly<{ max: number; ideal: readonly number[] }>;
  audio?: Readonly<{ format: string; channels: number; maxSeconds?: number; note?: string }>;
};

/** Mesh targets an adapter declares for meshgen output. Triangles are per asset; perCategory narrows them. */
export type AssetMeshBudget = {
  maxTriangles: number;
  maxMaterials: number;
  /** LOD triangle targets, highest first. meshgen does not build LODs yet (a non-empty list yields a warning). */
  lods: readonly number[];
  maxObjects?: number;
  maxGlbBytes?: number;
  /** Keyed by meshgen category ("weapon-ranged", "container", ...). */
  perCategory?: Readonly<Partial<Record<string, { maxTriangles?: number; maxExtentM?: number; minExtentM?: number }>>>;
};

export type ProfileIssue = { path: string; code: string; message: string };

/** Cheap structural rules a profile must satisfy; returns issues, never throws. */
export function validateAssetProfile(p: AssetProfile): ProfileIssue[] {
  const out: ProfileIssue[] = [];
  const add = (path: string, code: string, message: string) => out.push({ path, code, message });
  if (!DELIVERY_STRATEGIES.includes(p.delivery)) add("delivery", "bad_delivery", `unknown delivery strategy ${String(p.delivery)}`);
  if (!WORKER_CLASSES.includes(p.workerClass)) add("workerClass", "bad_worker_class", `unknown worker class ${String(p.workerClass)}`);
  if (!REQUIRED_GAME_FILES.includes(p.requiredGameFiles)) add("requiredGameFiles", "bad_required_files", `unknown value ${String(p.requiredGameFiles)}`);
  if ((p.legal.redistributeBase as unknown) !== false) add("legal.redistributeBase", "must_be_false", "a game's base assets are never redistributed");
  if ((p.legal.commercialOk === true || p.legal.aiOk === true) && !p.legal.reviewed) add("legal.reviewed", "unreviewed_claim", "commercialOk/aiOk can only be true after a human reviewed the policy");
  if (p.legal.reviewed && (!p.legal.policyUrl || !p.legal.retrievedAt)) add("legal.policyUrl", "missing_source", "a reviewed policy needs its url and retrieval date");
  if (p.maturity === "stable" && !p.legal.reviewed) add("maturity", "stable_needs_legal", "a stable adapter needs a reviewed legal policy");
  if (p.delivery === "client-manual" && p.maturity === "stable") add("delivery", "manual_not_stable", "assets players must install by hand cannot be a stable path");
  if (p.requiredGameFiles !== "none" && p.legal.attestationRequired !== true) add("legal.attestationRequired", "attestation_needed", "user-supplied or licensed game files need an ownership attestation");
  if (p.workerClass === "windows-tools" && p.requiredGameFiles === "platform-licensed") add("requiredGameFiles", "windows_licensed", "a Windows worker must not hold a platform-licensed game install without a separate legal review");
  if (!(p.maxTextureRes >= 16 && p.maxTextureRes <= 16384)) add("maxTextureRes", "bad_res", "maxTextureRes must be between 16 and 16384");
  if (p.channelMap.albedo && p.colorSpace.albedo && p.colorSpace.albedo !== "srgb") add("colorSpace.albedo", "albedo_srgb", "albedo is stored in sRGB");
  if (p.colorSpace.normal && p.colorSpace.normal !== "linear") add("colorSpace.normal", "normal_linear", "normal maps are linear data");
  if (p.channelMap.normal && p.normalConvention === "none") add("normalConvention", "normal_needs_convention", "a normal channel needs opengl or directx");
  if (p.meshBudget) {
    const b = p.meshBudget;
    if (!(Number.isInteger(b.maxTriangles) && b.maxTriangles >= 100)) add("meshBudget.maxTriangles", "bad_mesh_budget", "maxTriangles must be an integer >= 100");
    if (!(Number.isInteger(b.maxMaterials) && b.maxMaterials >= 1)) add("meshBudget.maxMaterials", "bad_mesh_budget", "maxMaterials must be an integer >= 1");
    if (b.lods.some((n, i) => n >= (i ? b.lods[i - 1] : b.maxTriangles))) add("meshBudget.lods", "bad_lods", "LOD targets must shrink, starting below maxTriangles");
    if (p.meshFormats.length === 0) add("meshBudget", "budget_without_format", "a mesh budget needs at least one mesh format");
  }
  if (p.motion) {
    const m = p.motion;
    if (m.game !== p.game) add("motion.game", "motion_game", `the motion capability is for ${m.game}, the profile for ${p.game}`);
    if (!(m.tickRate >= 1 && m.tickRate <= 240)) add("motion.tickRate", "motion_tick", "tickRate must be 1..240");
    if (m.attach && !m.nodeKinds.includes("seat") && !m.nodeKinds.includes("socket")) add("motion.attach", "motion_attach", "attach needs seat or socket nodes");
    if (m.trackKinds.material === "none" && m.materialChannels.length) add("motion.materialChannels", "motion_material", "material channels listed but material tracks are unsupported");
    for (const [k, v] of Object.entries(m.caps)) if (!(Number.isInteger(v) && v >= 0)) add(`motion.caps.${k}`, "motion_cap", `${k} must be a whole number >= 0`);
  }
  for (const role of Object.keys(p.channelMap)) if (!CHANNEL_ROLES.includes(role as ChannelRole)) add(`channelMap.${role}`, "bad_role", `unknown channel role ${role}`);
  return out;
}
// The game adapters the engine core knows about. Adding a game = one adapter file + one entry here.
import type { GameAdapter } from "./types";
import { minecraftAdapter } from "./minecraft";

export const ADAPTERS: readonly GameAdapter[] = [minecraftAdapter];

export function getAdapter(game: string): GameAdapter | null {
  return ADAPTERS.find((a) => a.game === game) ?? null;
}

export type { GameAdapter } from "./types";

// Game adapter #1: Minecraft Java (Paper / Purpur server plugins). Reads the version-support registry
// (lib/cyrus/versions) and the lifecycle facts in lib/cyrus/games/minecraft.ts; changes neither.
// Honest by default: only the plugin route is "available" today. Resource packs and data packs are on the
// roadmap (R1/R2), client mods are not something Cyrus builds. Pure, client-safe.
import { VERSIONS, getVersion, hasCapability, type Capability } from "../versions/registry";
import { legacyTexturesOn } from "../itemmodel/legacy";
import minecraft from "../games/minecraft";
import type { AdapterVersion, GameAdapter } from "./types";
import type { AssetProfile } from "./asset-profile";
import { minecraftMotionCapability } from "./motion-minecraft";

const toAdapterVersion = (v: (typeof VERSIONS)[number]): AdapterVersion => ({ id: v.id, status: v.status, buildable: v.buildable, capabilities: v.capabilities });
const PACK = "a resource pack the server sends to players when they join";

/** Minecraft Java asset profile. Legal fields stay "unknown"/unreviewed on purpose: the Mojang EULA and marketplace question is parked by the owner. */
export const minecraftAssetProfile: AssetProfile = {
  game: "minecraft",
  engineFamily: "minecraft-java",
  meshFormats: ["minecraft-model-json", "bbmodel"],
  textureFormats: ["png"],
  compression: ["png"],
  channelMap: { albedo: { file: "assets/<ns>/textures/<name>.png", channels: "rgba" } },
  normalConvention: "none",
  colorSpace: { albedo: "srgb" },
  maxTextureRes: 128, // TEXTURE_SIZES 16/32/64 and SKIN_TEXTURE_SIZES 64/128 (lib/cyrus/textures/dsl.ts)
  uvRules: "new",
  skeletonPolicy: "own",
  packaging: "zip resource pack",
  delivery: "server-streamed",
  workerClass: "linux-cpu",
  requiredGameFiles: "none",
  legal: { policyUrl: null, commercialOk: "unknown", aiOk: "unknown", redistributeBase: false, attestationRequired: false, retrievedAt: null, reviewed: false },
  validators: ["lib/cyrus/assets/textures.ts"],
  previewShader: "pixel-flat",
  maturity: "beta",
  catalog: {
    accepts: { sound: "convert", music: "convert", sprite: "convert", texture: "convert", model: "none", "texture-set": "none", hdri: "none", decal: "none",
      // r26 motion kinds: presets and effect frames go through the motion core; glTF clips / rigged meshes need a converter Cyrus lacks
      "motion-preset": "convert", "effect-preset": "convert", flipbook: "convert", "particle-texture": "convert", "animation-clip": "none", "animated-model": "none" },
    noneReasons: {
      model: "glTF meshes are not Minecraft models; Cyrus has no glTF-to-cuboid (bbmodel / item model JSON) converter yet",
      "texture-set": "Minecraft draws 16-64 px flat albedo; photoreal PBR sets do not read at that size",
      hdri: "Minecraft has no image-based lighting; skies need a client mod",
      decal: "Minecraft has no decal system",
    },
    styleAffinity: ["pixel-art", "one-bit"],
    textureRes: { max: 128, ideal: [16, 32, 64] },
    audio: { format: "ogg-vorbis", channels: 1, note: "transcoded to mono Ogg Vorbis (stereo ignores distance in Minecraft)" },
  },
  motion: minecraftMotionCapability,
};

export const minecraftAdapter: GameAdapter = {
  game: "minecraft",
  name: "Minecraft",
  maturity: "beta",
  defaultRoute: "plugin",
  artifacts: [
    { route: "plugin", availability: "available", packaging: "jar", side: "server", note: "A Paper/Purpur server plugin. Players join with a normal Minecraft, nothing to install." },
    { route: "resourcePack", availability: "planned", packaging: "zip", side: "client", note: `Textures, models, sounds and glyph HUDs ship as ${PACK}. Cyrus does not build or host resource packs yet.` },
    { route: "dataPack", availability: "planned", packaging: "zip", side: "server", note: "Recipes, loot tables, advancements, tags, functions and enchantments as a data pack built for the exact Minecraft version (the Cyrus data pack studio, switched off until Nxeon turns it on). World generation is not built yet." },
    { route: "clientMod", availability: "unsupported", packaging: "jar", side: "client", note: "Client mods (Fabric/NeoForge) would have to be installed by every player. Cyrus builds server-side mods only." },
  ],
  toolchain: {
    language: "Java",
    compiler: "javac --release <jdk> -proc:none against the Paper API classpath (services/modbuilder/server.js)",
    releaseFor: (id) => {
      const v = getVersion(id);
      return v && v.buildable ? String(v.javaRelease) : null;
    },
    scanner: "services/modbuilder/scan.js",
  },
  knowledge: { kind: "version-sheets", ref: "services/modbuilder/sheets/<version>.md" },
  versions: {
    list: () => VERSIONS.map(toAdapterVersion),
    get: (id) => {
      const v = getVersion(id);
      return v ? toAdapterVersion(v) : null;
    },
    // legacyCustomModelData is a fact in the registry, but only counts while the portal routes to it (CYRUS_LEGACY_TEXTURES)
    hasCapability: (id, c) => hasCapability(id, c as Capability) && (c !== "legacyCustomModelData" || legacyTexturesOn()),
  },
  assetDelivery: {
    texture: { supported: true, via: "server-pushed-pack", availability: "planned", note: `Item and mob textures reach players in ${PACK}.` },
    sound: { supported: true, via: "server-pushed-pack", availability: "planned", note: `Custom sounds reach players in ${PACK}.` },
    model: { supported: true, via: "server-pushed-pack", availability: "planned", note: `Item models and display-entity models reach players in ${PACK}.` },
    ui: { supported: true, via: "server-pushed-pack", availability: "planned", note: `Menu art and glyph HUDs are font glyphs in ${PACK}.` },
  },
  install: {
    side: minecraft.install.side,
    serverPath: minecraft.install.serverPath,
    needsRestart: minecraft.install.needsRestart,
    hotReload: minecraft.install.hotReload,
    summary: minecraft.install.reason,
  },
  testLane: {
    compile: true,
    scan: true,
    boot: "planned",
    functional: "planned",
    notes: minecraft.verification.notes,
  },
  assetProfile: minecraftAssetProfile,
  routeRules: [
    {
      id: "custom_block", route: "clientMod",
      keywords: ["\\bcustom blocks?\\b", "\\bnew block types?\\b", "\\bbrand[- ]new blocks?\\b", "\\bnew kinds? of blocks?\\b"],
      limit: { severity: "warn", message: "Brand-new block types need a client mod. A vanilla client can show retextured existing blocks or display-entity look-alikes instead." },
    },
    {
      id: "freeform_hud", route: "clientMod",
      keywords: ["\\bminimap\\b", "\\bcustom hud\\b", "\\bhud widgets?\\b", "\\bfree[- ]form hud\\b", "\\bhud overlays?\\b"],
      limit: { severity: "warn", message: "Free-form HUD widgets need a client mod. A server can show glyph-based HUD text (action bar, boss bar, scoreboard) with a resource pack font." },
    },
    {
      id: "keybind", route: "clientMod",
      keywords: ["\\bkey ?binds?\\b", "\\bkey ?bindings?\\b", "\\bhotkeys?\\b", "\\bcustom keys?\\b"],
      limit: { severity: "warn", message: "Custom keybinds need a client mod. Use commands, item clicks, sneaking or the swap-hands key instead." },
    },
    {
      id: "custom_sky", route: "clientMod",
      keywords: ["\\bcustom sky\\b", "\\bskybox\\b", "\\bshaders?\\b"],
      limit: { severity: "warn", message: "A custom sky or shaders need a client mod; a server cannot change how the client renders the sky." },
    },
    {
      id: "entity_model", route: "resourcePack",
      keywords: ["\\bcustom (?:mob|entity|creature) models?\\b", "\\banimated (?:mobs?|models?|creatures?)\\b", "\\b3d models?\\b"],
      assetKinds: ["model"],
      buildAssetKinds: ["creature"],
      limit: { severity: "info", message: "Animated custom creatures are display-entity models run by the Nxeon-managed BetterModel plugin on an invisible, silenced vanilla mob; players accept a resource pack on join, and Bedrock players (Geyser) see the plain base mob. Native entity types still need a client mod." },
      requiresCapability: { capability: "animatedCreatures", downgrade: true, message: "Animated custom creatures need Minecraft 26.x; on {version} Cyrus builds the plugin with custom sounds (and a static item-style model later) on a vanilla-looking mob." },
    },
    {
      id: "dialog",
      keywords: ["\\bdialogs?\\b", "\\bdialogue (?:box|boxes|screens?|windows?)\\b"],
      requiresCapability: { capability: "dialogApi", message: "The Dialog API needs Minecraft 1.21.7 or newer, and this mod targets {version}. A chest-menu GUI works on every version." },
    },
    {
      id: "item_model", route: "resourcePack",
      keywords: ["\\bcustom (?:item )?textures?\\b", "\\bcustom (?:item )?models?\\b", "\\bitem models?\\b", "\\bretextur\\w*"],
      assetKinds: ["texture", "model"],
      requiresCapability: { capability: "itemModelDefinitions", message: "Custom item models need Minecraft 1.21.4 or newer (item model definitions), and this mod targets {version}.",
        fallback: { capability: "legacyCustomModelData", message: "On {version} custom item looks use the older custom-model-data method: each look rides on a plain vanilla carrier item (a sword, tool, stick, gem, ingot or some food), another resource pack that changes the same vanilla item can clash with it, and per-state looks (pulling, aiming, modes, per-context) are not available; only worn-down (damage) looks are." } },
    },
    {
      id: "custom_sound", route: "resourcePack",
      keywords: ["\\bcustom sounds?\\b", "\\bnew sounds?\\b", "\\bcustom music\\b"],
      assetKinds: ["sound"],
      limit: { severity: "info", message: "Custom sounds travel in a server-pushed resource pack; players accept the pack when they join." },
    },
    { id: "glyph_ui", route: "resourcePack", keywords: ["\\bcustom (?:gui|menu) (?:art|textures?|backgrounds?)\\b", "\\bglyphs?\\b"], assetKinds: ["ui"] },
    {
      id: "worldgen", route: "dataPack",
      keywords: ["\\bbiomes?\\b", "\\bdimensions?\\b", "\\bworld ?gen(?:eration)?\\b", "\\bcustom structures?\\b", "\\bnew structures?\\b"],
      limit: { severity: "warn", message: "World generation (biomes, structures, dimensions) is not built into Cyrus yet; it would also need a full server restart, because /reload does not reload world generation." },
    },
    // Cyrus R2 data pack studio: data-driven content (lib/cyrus/datapack). The ids below are DATAPACK_RULES in lib/cyrus/datapack/route.ts.
    { id: "datapack_recipe", route: "dataPack", keywords: ["\\b(?:custom|new|extra|crafting|smelting|furnace|stonecutter|smithing) recipes?\\b", "\\brecipes? for\\b", "\\bcraftable\\b"],
