// the game's AssetProfile (lib/cyrus/adapters/asset-profile.ts, incl. its optional `catalog` hints) and the asset's
// own facts. Rules (honest by construction):
//   good = usable now as is, or through a converter Cyrus HAS (sound -> mono Ogg), and in a style the game likes
//   ok   = usable now but off-style, or over budget in a way Cyrus can live with (noted)
//   no   = needs something Cyrus does not have (a mesh converter, a downscaler) or the game cannot use the kind
// A game without catalog hints gets NO row: missing = unknown, and ranking treats unknown below ok.
import type { AssetProfile } from "../../adapters/asset-profile";
import type { CatalogKind, GameFit, Tech } from "./entry";

export type FitSubject = { kind: CatalogKind; style: string | null; tags: readonly string[]; categories: { primary: string; secondary: readonly string[] }; tech: Tech };

/** Transforms that EXIST in Cyrus today (a fit may only rely on these). */
export const AVAILABLE_TRANSFORMS = ["ogg-mono", "loudness-normalise", "motion-lower"] as const;

const isAudio = (k: CatalogKind) => k === "sound" || k === "music";
const charLike = (s: FitSubject) => s.categories.primary.startsWith("characters/") || s.categories.primary.startsWith("creatures/");
const vehicleLike = (s: FitSubject) => s.categories.primary.startsWith("vehicles/");

export function gameFit(s: FitSubject, profile: AssetProfile): GameFit | null {
  const h = profile.catalog;
  if (!h) return null;
  const mode = h.accepts[s.kind] ?? "none";
  const notes: string[] = [`delivery: ${profile.delivery}`];
  if (mode === "none") return { fit: "no", reason: (h.noneReasons?.[s.kind] ?? `${profile.game} cannot use ${s.kind} assets`).slice(0, 200), notes: [], transform: [] };
  const styleOk = !h.styleAffinity.length || (s.style != null && h.styleAffinity.includes(s.style)) || s.tags.some((t) => h.styleAffinity.includes(t));

  if (isAudio(s.kind)) {
    const a = h.audio;
    const transform: string[] = [];
    if (a) {
      notes.push(`target ${a.format}, ${a.channels === 1 ? "mono" : `${a.channels} ch`}`);
      if (a.note) notes.push(a.note);
      if (s.tech.channels == null || s.tech.channels !== a.channels || s.tech.format !== a.format) transform.push("ogg-mono");
    }
    transform.push("loudness-normalise");
    if (a?.maxSeconds && s.tech.durationS != null && s.tech.durationS > a.maxSeconds) return { fit: "ok", reason: `longer than ${a.maxSeconds} s; trim before use`, notes, transform };
    if (s.tech.durationS == null) return { fit: "ok", reason: "audio not measured yet", notes, transform };
    return { fit: "good", reason: transform.includes("ogg-mono") ? "plays after the standard mono Ogg transcode" : "plays as is", notes, transform };
  }
