// Cyrus 3D assets: the LEGAL LEDGER (classes + what each may do), pure and client-safe with no imports, so the studios'
// client code (Model Studio layer 3 badge) and the server (manifest validation, library eligibility) read ONE copy.
// ./manifest.ts re-exports everything here.

/** user-original / ai-generated-for-user / platform-library (Nxeon-owned or CC0 only) / third-party-licensed / game-derived. */
export const LEGAL_CLASSES = ["user-original", "ai-generated-for-user", "platform-library", "third-party-licensed", "game-derived"] as const;
export type LegalClass = (typeof LEGAL_CLASSES)[number];

/** What the ledger allows for a class. The rule: game-derived content never outlives its job, never enters a library, never ships. */
export type LedgerRules = { storeBeyondJob: boolean; addToLibrary: boolean; redistribute: boolean; deliverable: "full" | "delta-only" };
export function ledgerRules(c: LegalClass): LedgerRules {
  switch (c) {
    case "game-derived": return { storeBeyondJob: false, addToLibrary: false, redistribute: false, deliverable: "delta-only" };
    case "third-party-licensed": return { storeBeyondJob: true, addToLibrary: false, redistribute: false, deliverable: "full" };
    // Owner decision 2026-10-10: assets made in Cyrus contribute to the community library automatically (no opt-in).
    default: return { storeBeyondJob: true, addToLibrary: true, redistribute: true, deliverable: "full" };
  }
}

/**
 * Whether a manifest is eligible for automatic contribution to the community library. Eligible = made inside Cyrus
 * (user-original authored in a studio, ai-generated-for-user) or already Nxeon's own, and not derived from any other bytes.
 * Never: game-derived, third-party-licensed, imported/uploaded/template content, or anything with a derivedFrom entry. Eligible is not published: the
 * content filters (trademark, real-weapon, adult content) and the terms-of-service grant still gate publication.
 */
export function libraryEligible(m: { legalClass: LegalClass; provenance: { source: string; derivedFrom: readonly string[] } }): boolean {
  if (!ledgerRules(m.legalClass).addToLibrary) return false;
  // Only content authored inside Cyrus from nothing outside it: no imports/uploads/templates, and nothing derived from other bytes
  // (a livery painted on someone's template lists that template in derivedFrom, so it is never auto-contributed).
  if (!["user", "ai", "library"].includes(m.provenance.source)) return false;
  return m.provenance.derivedFrom.length === 0;
}

