// Cyrus game onboarding kit: the typed half of docs/cyrus/onboarding/PLAYBOOK.md. One OnboardingRecord per game
// (docs/cyrus/onboarding/games/<id>/record.json) says which playbook phase the game is in, which owner gates are
// signed, which studios the team intends to light up, and the EVIDENCE behind the maturity its adapter claims.
// Pure, client-safe, no Nxeon imports (host seam). The checklist itself is markdown (games/<id>/TODO.md, ./todo.ts).

/** Bump with every playbook change; PLAYBOOK.md and CHANGELOG.md carry the same string (test/cyrus-onboarding.test.ts). */
export const PLAYBOOK_VERSION = "1.0.0";

/** Game ids follow the Cyrus game registry rule (lib/cyrus/game-status.ts GAME_STATUS_KEY_RE). */
export const GAME_ID_RE = /^[a-z0-9]{2,20}$/;

export const PHASES = [
  { n: 0, id: "screening", title: "Screening (go / no-go)" },
  { n: 1, id: "research", title: "Deep research" },
  { n: 2, id: "capability", title: "Capability mapping" },
  { n: 3, id: "tooling", title: "Tooling decisions" },
  { n: 4, id: "knowledge", title: "Knowledge + build" },
  { n: 5, id: "assets", title: "Assets for the library" },
  { n: 6, id: "verification", title: "Verification" },
  { n: 7, id: "legal", title: "Legal + security review" },
  { n: 8, id: "integration", title: "Nxeon integration" },
  { n: 9, id: "launch", title: "Launch + upkeep" },
] as const;
export type PhaseId = (typeof PHASES)[number]["id"];
export type PhaseNumber = (typeof PHASES)[number]["n"];
export const PHASE_IDS: readonly PhaseId[] = PHASES.map((p) => p.id);
export const phaseNumber = (id: PhaseId): number => PHASES.find((p) => p.id === id)!.n;

/**
 * active = being onboarded; on-hold = parked by the owner (kept as a case study); reference = the reference implementation
 * (Minecraft); live = launched and in upkeep; rejected = screening said no-go (kept so nobody redoes the research).
 */
export const ONBOARDING_STATUSES = ["active", "on-hold", "reference", "live", "rejected"] as const;
export type OnboardingStatus = (typeof ONBOARDING_STATUSES)[number];

/** The adapter maturity ladder (same words as lib/cyrus/adapters/types.ts AdapterMaturity). */
export const MATURITY_LADDER = ["planned", "template", "beta", "stable"] as const;
export type Maturity = (typeof MATURITY_LADDER)[number];

/** Owner gates of the playbook. A gate is signed only by the owner (never by an agent): `by` + `at` filled in by hand. */
export const OWNER_GATES = [
  { id: "G0-go", phase: "screening", title: "Owner says GO on the screening scorecard" },
  { id: "G1-research", phase: "research", title: "Owner accepts the research report (unknowns listed, nothing invented)" },
  { id: "G3-tooling", phase: "tooling", title: "Owner approves new apps / workers / licences / costs from the tooling decision" },
  { id: "G5-assets", phase: "assets", title: "Owner approves the asset sources and the licence ledger for this game" },
  { id: "G6-beta", phase: "verification", title: "Owner approves the maturity bump to beta (evidence attached)" },
  { id: "G7-legal", phase: "legal", title: "Owner (or counsel) read the EULA / mod policy / AI terms and flips legal.reviewed" },
  { id: "G8-flags", phase: "integration", title: "Owner approves the flag order and the plan gating" },
  { id: "G9-launch", phase: "launch", title: "Owner flips the game to live (the catalog status), after the launch checklist" },
] as const;
export type OwnerGateId = (typeof OWNER_GATES)[number]["id"];

export type GateSignature = { by: string; at: string; note?: string };

/** One piece of evidence: a repo path, an agent-notes report or a recorded run file, with the date it was produced. */
export type EvidenceRef = { ref: string; at: string; note?: string };
/** A measured rate (never an estimate). */
export type RateEvidence = EvidenceRef & { passed: number; total: number };

export type MaturityEvidence = {
  /** canned/template output exists and passes its own validator (template). */
  templateValidated?: EvidenceRef;
  /** real AI build path: generated code compiles with the game's toolchain (beta). */
  compile?: RateEvidence;
  /** the game's safety scan / validator runs on every build (beta). */
  scan?: EvidenceRef;
  /** eval set run with the real build path (beta: >= 40 prompts measured). */
  eval?: RateEvidence;
  /** headless boot + functional checks (Test Flight equivalent) on real server software (stable). */
  flight?: RateEvidence;
  /** a human joined with a real client and saw the features work (stable). */
  realClientDay?: EvidenceRef;
  /** legal.reviewed flipped by the owner, with the policy url read (stable). */
  legalReviewed?: EvidenceRef;
};

/** The studio / tool surfaces a game can light up (./manifest.ts derives the usable set from the adapter). */
export const STUDIO_IDS = [
  "texture-studio", "sound-studio", "model-studio", "motion-studio", "config-studio", "datapack-studio",
  "designers", "creatures", "library", "import", "modpacks", "testflight", "delivery", "doctor",
] as const;
export type StudioId = (typeof STUDIO_IDS)[number];

export type OnboardingRecord = {
  game: string;
  name: string;
  status: OnboardingStatus;
  /** the phase the game is IN (its exit criteria not yet met). */
  phase: PhaseId;
  /** the playbook version the record was last brought up to. */
  playbookVersion: string;
  /** repo path of the adapter file, or null when none exists yet. */
  adapterFile: string | null;
  /** repo path of the GameSupport file, or null. */
  supportFile: string | null;
  /** what the adapter claims; the health check holds it against `evidence`. */
  declaredMaturity: Maturity;
  evidence: MaturityEvidence;
  /** studios the game has a game-specific emitter / exporter for (phase 3 + 4 output). Derivation lives in ./manifest.ts. */
  emitters: StudioId[];
  gates: Partial<Record<OwnerGateId, GateSignature>>;
  /** why the game is on hold / rejected (required for those statuses). */
  holdReason?: string;
  /** research files this record is built on (reuse, never redo). */
  research: string[];
  updatedAt: string;
};

