// Onboarding health: the maturity ladder's exit criteria as code, and the checks that keep a game's record honest.
// "An adapter may not claim more maturity than its evidence shows" (MASTER-PLAN principle 2: evidence over claims).
// Pure, client-safe. test/cyrus-onboarding.test.ts runs checkRecord() over every record and fails on any error.
import {
  GAME_ID_RE, MATURITY_LADDER, ONBOARDING_STATUSES, OWNER_GATES, PHASE_IDS, STUDIO_IDS, phaseNumber,
  type Maturity, type MaturityEvidence, type OnboardingRecord, type OwnerGateId, type RateEvidence,
} from "./types";

/** Smallest sample a rate may be judged on (same floor as the public pass-rate page, lib/cyrus/eval/passrate.ts MIN_PUBLISH_N). */
export const MIN_SAMPLE = 10;

/** The exact exit criteria of each rung (PLAYBOOK.md section "Maturity ladder" prints this table). */
export const LADDER_CRITERIA = {
  planned: { summary: "Nothing built. Adapter file + GameSupport stub + record exist; every unknown is listed." },
  template: { summary: "Canned / template output exists and passes the game's validator.", needs: ["templateValidated"] },
  beta: {
    summary: "Real AI build path: compile >= 90% over >= 20 builds, the safety scan runs on every build, eval run >= 20 measured prompts at >= 80%; owner gate G6-beta signed.",
    needs: ["templateValidated", "compile", "scan", "eval"], compileMin: { total: 20, rate: 0.9 }, evalMin: { total: 20, rate: 0.8 },
  },
  stable: {
    summary: "Beta plus headless boot + functional flights >= 95% over >= 10 flights, one real-client day, legal reviewed by the owner (G7-legal) and a no-manual delivery path.",
    needs: ["templateValidated", "compile", "scan", "eval", "flight", "realClientDay", "legalReviewed"], flightMin: { total: MIN_SAMPLE, rate: 0.95 },
  },
} as const;

const rateOk = (r: RateEvidence | undefined, min: { total: number; rate: number }) =>
  !!r && Number.isInteger(r.passed) && Number.isInteger(r.total) && r.total >= min.total && r.passed <= r.total && r.passed / r.total >= min.rate;

/** The highest rung the evidence supports (gates are checked separately). */
export function evidenceMaturity(e: MaturityEvidence): Maturity {
  if (!e.templateValidated) return "planned";
  const beta = rateOk(e.compile, LADDER_CRITERIA.beta.compileMin) && !!e.scan && rateOk(e.eval, LADDER_CRITERIA.beta.evalMin);
  if (!beta) return "template";
  const stable = rateOk(e.flight, LADDER_CRITERIA.stable.flightMin) && !!e.realClientDay && !!e.legalReviewed;
  return stable ? "stable" : "beta";
}

export const rank = (m: Maturity) => MATURITY_LADDER.indexOf(m);

export type HealthIssue = { code: string; severity: "error" | "warn"; message: string };

const ISO_DAY = /^\d{4}-\d{2}-\d{2}/;

/**
 * Every rule a record must satisfy. `adapterMaturity` = what the adapter file really says (null = no adapter loaded).
 * Errors fail the onboarding health test; warnings are shown on the admin dashboard.
 */
export function checkRecord(r: OnboardingRecord, adapterMaturity: Maturity | null = null): HealthIssue[] {
  const out: HealthIssue[] = [];
  const err = (code: string, message: string) => out.push({ code, severity: "error", message });
  const warn = (code: string, message: string) => out.push({ code, severity: "warn", message });
  const signed = (g: OwnerGateId) => !!r.gates[g]?.by && !!r.gates[g]?.at;
  const grandfathered = r.status === "reference" || r.retrofit === true;

  if (!GAME_ID_RE.test(r.game)) err("bad_game_id", `game id "${r.game}" must match ${GAME_ID_RE}`);
  if (!ONBOARDING_STATUSES.includes(r.status)) err("bad_status", `unknown status ${String(r.status)}`);
  if (!PHASE_IDS.includes(r.phase)) err("bad_phase", `unknown phase ${String(r.phase)}`);
  if (!MATURITY_LADDER.includes(r.declaredMaturity)) err("bad_maturity", `unknown maturity ${String(r.declaredMaturity)}`);
  if (!ISO_DAY.test(r.updatedAt)) err("bad_date", "updatedAt must be an ISO date");
  for (const s of r.emitters) if (!STUDIO_IDS.includes(s)) err("bad_emitter", `unknown studio id ${s}`);
  for (const [g, sig] of Object.entries(r.gates)) {
    if (!OWNER_GATES.some((x) => x.id === g)) err("bad_gate", `unknown owner gate ${g}`);
