// Per-game CAPABILITY MANIFEST (playbook phase 2): which Cyrus studios / tools are usable, planned or hidden for one
// game, the routes it can build, the worker classes it needs, the game files it needs and the legal classes each asset
// kind may carry. DERIVED, never hand-written: inputs are the game's adapter (lib/cyrus/adapters) and the emitters
// the onboarding record lists (a studio needs a game-specific emitter / exporter before it is more than "planned").
// Pure, client-safe. When the r45 structure manifest lands, reconcile the two so there is one source (IMPROVEMENTS.md).
import type { GameAdapter } from "../adapters/types";
import type { AssetProfile, WorkerClass } from "../adapters/asset-profile";
import { ASSET_KINDS, type ArtifactRoute, type AssetKind } from "../engine-core/spec";
import { LEGAL_CLASSES, ledgerRules, type LegalClass } from "../assets3d/ledger";
import { STUDIO_IDS, type OnboardingRecord, type StudioId } from "./types";

export type StudioState = "usable" | "planned" | "hidden";
export type StudioRow = { id: StudioId; name: string; state: StudioState; reason: string };

export const STUDIO_NAMES: Readonly<Record<StudioId, string>> = {
  "texture-studio": "Texture Studio", "sound-studio": "Sound Studio", "model-studio": "Model Studio", "motion-studio": "Motion Studio",
  "config-studio": "Config Studio", "datapack-studio": "Data Pack Studio", designers: "Gameplay designers", creatures: "Creature pipeline",
  library: "Asset library fit", import: "Import your own mod", modpacks: "Mod Packs + conflict engine", testflight: "Test Flight",
  delivery: "Install onto Nxeon servers", doctor: "Server Doctor",
};

type Need = { ok: boolean; why: string; deliveryKind?: AssetKind };
const routeOpen = (a: GameAdapter, r: ArtifactRoute) => a.artifacts.some((x) => x.route === r && x.availability !== "unsupported");

/** What the ADAPTER must declare for a studio to make sense at all (game-agnostic rules). */
function adapterNeed(id: StudioId, a: GameAdapter, p: AssetProfile | undefined): Need {
  switch (id) {
    case "texture-studio": return { ok: a.assetDelivery.texture.supported && !!p?.textureFormats.length, why: "needs a texture delivery path and texture formats in the asset profile", deliveryKind: "texture" };
    case "sound-studio": return { ok: a.assetDelivery.sound.supported, why: "needs a sound delivery path", deliveryKind: "sound" };
    case "model-studio": return { ok: a.assetDelivery.model.supported && !!p?.meshFormats.length, why: "needs a model delivery path and mesh formats in the asset profile", deliveryKind: "model" };
    case "motion-studio": return { ok: !!p?.motion, why: "needs a motion capability in the asset profile (lib/cyrus/motion/caps.ts)" };
    case "creatures": return { ok: a.assetDelivery.model.supported && !!p?.motion && p.skeletonPolicy !== "forbidden", why: "needs models + motion and a skeleton policy that is not forbidden", deliveryKind: "model" };
    case "datapack-studio": return { ok: routeOpen(a, "dataPack"), why: "needs a dataPack route" };
    case "designers": return { ok: routeOpen(a, "plugin"), why: "needs a server code route (plugin) for the generated gameplay" };
    case "library": return { ok: !!p?.catalog, why: "needs catalog fit hints in the asset profile (lib/cyrus/library/v2/fit.ts)" };
    case "testflight": return { ok: a.testLane.boot !== "none", why: "needs a headless boot lane (testLane.boot)" };
    case "delivery": return { ok: a.install.side !== "client", why: "needs a server-side install path; client-only mods cannot be installed by Nxeon" };
    case "config-studio": case "import": case "modpacks": case "doctor": return { ok: true, why: "" };
  }
}

export function studioRows(adapter: GameAdapter | null, emitters: readonly StudioId[]): StudioRow[] {
  return STUDIO_IDS.map((id) => {
    const row = (state: StudioState, reason: string): StudioRow => ({ id, name: STUDIO_NAMES[id], state, reason });
    if (!adapter) return row("hidden", "no adapter yet (phase 2)");
    const need = adapterNeed(id, adapter, adapter.assetProfile);
    if (!need.ok) return row("hidden", need.why);
    if (!emitters.includes(id)) return row("planned", `the adapter can carry it; no ${adapter.game} emitter / exporter yet (phases 3-4)`);
    if (need.deliveryKind && adapter.assetDelivery[need.deliveryKind].availability !== "available") return row("planned", `${need.deliveryKind} delivery is ${adapter.assetDelivery[need.deliveryKind].availability}, not available`);
    if (adapter.maturity === "planned") return row("planned", "the adapter is at maturity planned");
    return row("usable", "adapter + emitter + delivery in place");
  });
}

export type LegalClassRow = { kind: AssetKind; allowed: { cls: LegalClass; storage: "kept" | "job-only"; library: boolean }[] };

/** Which ledger classes each asset kind may carry for this game (lib/cyrus/assets3d/ledger.ts is the rulebook). */
export function legalClasses(p: AssetProfile | undefined): LegalClassRow[] {
  return ASSET_KINDS.map((kind) => ({
    kind,
    allowed: LEGAL_CLASSES.filter((c) => c !== "game-derived" || (p && p.requiredGameFiles !== "none")).map((cls) => {
      const r = ledgerRules(cls);
      return { cls, storage: r.storeBeyondJob ? "kept" as const : "job-only" as const, library: r.addToLibrary };
    }),
  }));
}

export type CapabilityManifest = {
  game: string;
  maturity: string;
  routes: { route: ArtifactRoute; availability: string; packaging: string; side: string }[];
  studios: StudioRow[];
  workerClasses: WorkerClass[];
  requiredGameFiles: string;
  delivery: string;
  testFlight: { boot: string; functional: string };
  languages: string[];
  legal: LegalClassRow[];
};

export function capabilityManifest(adapter: GameAdapter | null, record: Pick<OnboardingRecord, "game" | "emitters" | "declaredMaturity">): CapabilityManifest {
  const p = adapter?.assetProfile;
  return {
    game: record.game,
    maturity: adapter?.maturity ?? record.declaredMaturity,
    routes: (adapter?.artifacts ?? []).map((x) => ({ route: x.route, availability: x.availability, packaging: x.packaging, side: x.side })),
    studios: studioRows(adapter, record.emitters),
    workerClasses: p ? [p.workerClass] : ["linux-cpu"],
    requiredGameFiles: p?.requiredGameFiles ?? "unknown",
    delivery: p?.delivery ?? "unknown",
    testFlight: { boot: adapter?.testLane.boot ?? "none", functional: adapter?.testLane.functional ?? "none" },
    languages: adapter ? [adapter.toolchain.language] : [],
    legal: legalClasses(p),
  };
}

