// The per-game onboarding checklist (docs/cyrus/onboarding/games/<id>/TODO.md): markdown so agents and the owner tick it
// by hand. Phase sections are "## P<n> <title>", items are "- [ ]" / "- [x]", an owner gate item contains "OWNER GATE <id>".
// parseTodo is pure (unit-tested); the admin dashboard and the health test read it.
import { PHASES } from "./types";

export type TodoItem = { text: string; done: boolean; gate: string | null };
export type TodoPhase = { n: number; title: string; items: TodoItem[]; done: number; total: number; gatesOpen: string[] };
export type TodoSummary = { phases: TodoPhase[]; done: number; total: number; gatesOpen: string[]; currentPhase: number | null };

const clean = (s: string) => s.replace(/\*\*/g, "").replace(/`/g, "").replace(/\s+/g, " ").trim().slice(0, 300);

export function parseTodo(md: string): TodoSummary {
  const phases: TodoPhase[] = [];
  let cur: TodoPhase | null = null;
  for (const line of md.replace(/\r/g, "").split("\n")) {
    const h = /^##\s+P(\d)\b\s*(.*)$/.exec(line);
    if (h) {
      const n = Number(h[1]);
      cur = { n, title: clean(h[2]) || PHASES[n]?.title || `Phase ${n}`, items: [], done: 0, total: 0, gatesOpen: [] };
      phases.push(cur);
      continue;
    }
    if (/^#{1,2}\s/.test(line)) { cur = null; continue; }
    const cb = /^\s*[-*]\s+\[( |x|X)\]\s+(.*)$/.exec(line);
    if (!cur || !cb) continue;
    const text = clean(cb[2]);
    const gate = /OWNER GATE\s+(G\d-[a-z]+)/.exec(text)?.[1] ?? null;
    const done = cb[1] !== " ";
    cur.items.push({ text, done, gate });
    cur.total++;
    if (done) cur.done++;
    else if (gate) cur.gatesOpen.push(gate);
  }
  const done = phases.reduce((s, p) => s + p.done, 0);
  const total = phases.reduce((s, p) => s + p.total, 0);
  const open = phases.find((p) => p.done < p.total);
  return { phases, done, total, gatesOpen: phases.flatMap((p) => p.gatesOpen), currentPhase: open ? open.n : phases.length ? null : 0 };
}

