// Reads the onboarding records + checklists from docs/cyrus/onboarding/games/<id>/ (server only: node:fs).
// Same file convention as lib/cyrus/admin/readiness.ts: the repo copy is what production reads.
import { readdir, readFile } from "node:fs/promises";
import { join } from "node:path";
import { getAdapter } from "../adapters";
import type { GameAdapter } from "../adapters/types";
import { capabilityManifest, type CapabilityManifest } from "./manifest";
import { checkRecord, evidenceMaturity, type HealthIssue } from "./health";
import { parseTodo, type TodoSummary } from "./todo";
import { GAME_ID_RE, type Maturity, type OnboardingRecord } from "./types";

export const ONBOARDING_DIR = join("docs", "cyrus", "onboarding", "games");

export type OnboardingView = {
  record: OnboardingRecord;
  todo: TodoSummary | null;
  issues: HealthIssue[];
  proven: Maturity;
  manifest: CapabilityManifest;
  /** true when the adapter is registered in lib/cyrus/adapters/index.ts (the router can see it). */
  registered: boolean;
};

export async function listOnboardingIds(root = process.cwd()): Promise<string[]> {
  try {
    const ents = await readdir(join(root, ONBOARDING_DIR), { withFileTypes: true });
    return ents.filter((e) => e.isDirectory() && GAME_ID_RE.test(e.name)).map((e) => e.name).sort();
  } catch {
    return [];
  }
}

export async function loadOnboarding(gameId: string, opts: { root?: string; adapter?: GameAdapter | null } = {}): Promise<OnboardingView | null> {
  if (!GAME_ID_RE.test(gameId)) return null;
  const dir = join(opts.root ?? process.cwd(), ONBOARDING_DIR, gameId);
  let record: OnboardingRecord;
  try {
    record = JSON.parse(await readFile(join(dir, "record.json"), "utf8")) as OnboardingRecord;
  } catch {
    return null;
  }
  let todo: TodoSummary | null = null;
  try { todo = parseTodo((await readFile(join(dir, "TODO.md"), "utf8")).slice(0, 200_000)); } catch { /* no checklist */ }
  const registered = getAdapter(gameId);
  const adapter = opts.adapter !== undefined ? opts.adapter : registered;
  return {
    record, todo, registered: !!registered,
    issues: checkRecord(record, adapter ? adapter.maturity : null),
    proven: evidenceMaturity(record.evidence),
    manifest: capabilityManifest(adapter, record),
  };
}

