// Cyrus game onboarding scaffolder (docs/cyrus/onboarding/PLAYBOOK.md). Generates the skeleton of a new game:
//   lib/cyrus/adapters/<id>.ts           GameAdapter at maturity "planned" + AssetProfile draft (legal.reviewed false)
//   lib/cyrus/games/<id>.ts              GameSupport stub (everything unknown is listed in `unknowns`)
//   lib/cyrus/games/<id>.knowledge.ts    empty knowledge pack
//   services/modbuilder/eval/games/<id>.jsonl   eval-set stub: 30 prompt slots + 10 adversarial slots, all `todo`
//   docs/cyrus/onboarding/games/<id>/    record.json (phase screening, capability manifest inputs) + TODO.md + doc stubs
// IDEMPOTENT: an existing file is never overwritten (reported as "kept"), so a second run changes nothing.
// SAFE: it registers nothing. The adapter is NOT added to lib/cyrus/adapters/index.ts, the game is NOT added to
// lib/cyrus/games.ts, no flag or setting is written: those are owner-gated playbook steps (TODO.md lists them).
//
//   npx tsx scripts/cyrus/new-game.ts <gameId> [--name "Game Name"] [--language Java|C#|Lua|C++|JSON/data]
//       [--engine minecraft-java|unreal|unity|source|rage|creation|hytale|other] [--docs-only] [--dry-run] [--root DIR]
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { GAME_ID_RE, OWNER_GATES, PLAYBOOK_VERSION, type OnboardingRecord } from "../../lib/cyrus/onboarding/types";

export const LANGUAGES = ["Java", "C#", "Lua", "C++", "JSON/data"] as const;
export const ENGINES = ["minecraft-java", "unreal", "unity", "source", "rage", "creation", "hytale", "other"] as const;

export type ScaffoldOptions = {
  gameId: string;
  name?: string;
  language?: (typeof LANGUAGES)[number];
  engine?: (typeof ENGINES)[number];
  docsOnly?: boolean;
  dryRun?: boolean;
  root?: string;
  /** ISO day written into the stubs (tests pin it). */
  date?: string;
};
export type ScaffoldFile = { path: string; content: string };
export type ScaffoldReport = { gameId: string; created: string[]; kept: string[]; dryRun: boolean };

/** Doc stubs: games/<id>/<out> generated from templates/<template>. */
export const DOC_STUBS: readonly { out: string; template: string }[] = [
  { out: "TODO.md", template: "TODO.md" },
  { out: "SCORECARD.md", template: "SCREENING-SCORECARD.md" },
  { out: "RESEARCH.md", template: "RESEARCH-REPORT.md" },
  { out: "CAPABILITY.md", template: "CAPABILITY-WORKSHEET.md" },
  { out: "ADAPTER.md", template: "ADAPTER-CHECKLIST.md" },
  { out: "ASSETS.md", template: "ASSET-SOURCING.md" },
  { out: "LEGAL.md", template: "LEGAL-CHECKLIST.md" },
  { out: "VERIFICATION.md", template: "VERIFICATION-PLAN.md" },
  { out: "LAUNCH.md", template: "LAUNCH-CHECKLIST.md" },
];

const ident = (id: string) => (/^[0-9]/.test(id) ? `game${id}` : id);
const titleCase = (id: string) => id.charAt(0).toUpperCase() + id.slice(1);
const today = () => new Date().toISOString().slice(0, 10);

export const EVAL_SLOTS = { prompts: 30, adversarial: 10 } as const;

function adapterFile(id: string, name: string, language: string, engine: string): string {
  const v = ident(id);
  return `// Game adapter: ${name} (${id}). GENERATED by scripts/cyrus/new-game.ts at maturity "planned": nothing is built.
// Fill it in during playbook phase 2 (docs/cyrus/onboarding/PLAYBOOK.md, worksheet games/${id}/CAPABILITY.md).
// NOT registered in lib/cyrus/adapters/index.ts on purpose: registering is an owner-gated step (games/${id}/TODO.md).
// Every "unknown" here is honest: replace it only with a fact you verified (cite the url in lib/cyrus/games/${id}.ts sources).
import type { GameAdapter } from "./types";
import type { AssetProfile } from "./asset-profile";

/** DRAFT asset profile. legal.reviewed stays false until the owner reads the policy (gate G7-legal). */
export const ${v}AssetProfile: AssetProfile = {
  game: "${id}",
  engineFamily: "${engine}",
  meshFormats: [],
  textureFormats: [],
  compression: [],
  channelMap: {},
  normalConvention: "none",
  colorSpace: {},
  maxTextureRes: 256, // PLACEHOLDER: not researched yet (phase 1 asset formats)
  uvRules: "none",
  skeletonPolicy: "none",
  packaging: "unknown",
  delivery: "none",
  workerClass: "linux-cpu",
  requiredGameFiles: "none",
  legal: { policyUrl: null, commercialOk: "unknown", aiOk: "unknown", redistributeBase: false, attestationRequired: true, retrievedAt: null, reviewed: false },
  validators: [],
  previewShader: "none",
  maturity: "planned",
};

export const ${v}Adapter: GameAdapter = {
  game: "${id}",
  name: "${name}",
  maturity: "planned",
  defaultRoute: "plugin",
  artifacts: [
    { route: "plugin", availability: "planned", packaging: "unknown", side: "server", note: "Server-side mods for ${name} are being researched. Nothing can be built yet." },
    { route: "clientMod", availability: "unsupported", packaging: "unknown", side: "client", note: "Cyrus builds nothing players must install by hand." },
  ],
  toolchain: {
    language: "${language}",
    compiler: "none yet (playbook phase 4)",
    releaseFor: () => null,
    scanner: "none yet (playbook phase 4)",
  },
  knowledge: { kind: "knowledge-pack", ref: "lib/cyrus/games/${id}.knowledge.ts" },
  versions: { list: () => [], get: () => null, hasCapability: () => false },
  assetDelivery: {
    texture: { supported: false, via: "none", availability: "none", note: "Not researched yet." },
    sound: { supported: false, via: "none", availability: "none", note: "Not researched yet." },
    model: { supported: false, via: "none", availability: "none", note: "Not researched yet." },
    ui: { supported: false, via: "none", availability: "none", note: "Not researched yet." },
  },
  install: { side: "server", serverPath: "unknown", needsRestart: true, hotReload: false, summary: "Install rules are not researched yet." },
  testLane: { compile: false, scan: false, boot: "none", functional: "none", notes: "No verification lane yet (playbook phase 4 + 6)." },
  routeRules: [],
  assetProfile: ${v}AssetProfile,
};

export default ${v}Adapter;
`;
}

function supportFile(id: string, name: string, language: string): string {
  const v = ident(id);
  return `/**
 * ${name} modding support for Cyrus (PURE, client-safe, data only). GENERATED by scripts/cyrus/new-game.ts: a stub.
 * Fill it from the phase 1 research (docs/cyrus/onboarding/games/${id}/RESEARCH.md). Facts must be VERIFIED against the
 * loader's own docs/source with the url in \`sources\`; anything not confirmed stays in \`unknowns\`.
 */
import type { GameSupport } from "./support";
import { ${v.toUpperCase()}_KNOWLEDGE } from "./${id}.knowledge";

const support: GameSupport = {
  id: "${id}",
  name: "${name}",
  builds: "Not decided yet (playbook phase 0 screening).",
  language: "${language}",
  loader: { name: "unknown", homepage: "", installDocs: "" },
  versions: [],
  install: { side: "server", serverPath: "unknown", needsRestart: true, hotReload: false, packaging: "zip", reason: "Not researched yet." },
  verification: { method: "none", notes: "Nothing verified yet.", canRunSandbox: false },
  dangerousApis: [],
  breakageRisks: [],
  outdatedSignals: [],
  categories: [],
  examplePrompts: [],
  knowledge: ${v.toUpperCase()}_KNOWLEDGE,
  sources: [],
  unknowns: [
    "language + runtime + mod loader (phase 1 template: languages and runtimes, mod loaders/APIs)",
    "how mods and assets reach players: server-streamed, workshop or manual (phase 0 delivery)",
    "dedicated server on Linux, licence to host it for customers (phase 0 server availability)",
    "EULA / mod policy / AI and commercial terms (phase 0 + 7; legal.reviewed stays false)",
    "asset formats: mesh, texture, material, sound, animation, UI (phase 1)",
    "config conventions, networking, packaging and install path (phase 1)",
    "version cadence and the outdated signals (phase 1)",
    "headless boot / verification lane (phase 4 Test Flight equivalent)",
  ],
};

export default support;
`;
}

function knowledgeFile(id: string, name: string): string {
  return `// ${name} knowledge pack for Cyrus (PURE). GENERATED empty by scripts/cyrus/new-game.ts. Distilled, VERIFIED facts only:
// one API fact per apiSheet line, tagged "[Type] ...", and failure rules with a detect regex + fix + why
// (playbook phase 4). Never commit game binaries or decompiled output.
import type { KnowledgePack } from "./support";

export const ${ident(id).toUpperCase()}_KNOWLEDGE: KnowledgePack = { version: "unknown", apiSheet: [], failureRules: [] };
`;
}

function evalStub(id: string): string {
  const rows: string[] = [];
  for (let i = 1; i <= EVAL_SLOTS.prompts; i++) rows.push(JSON.stringify({ key: `${id}-p${String(i).padStart(2, "0")}`, game: id, todo: true, cls: i <= 10 ? "simple" : i <= 22 ? "standard" : "complex", category: "TODO", prompt: "TODO", checks: [], must_refuse: false, adversarial: false }));
  for (let i = 1; i <= EVAL_SLOTS.adversarial; i++) rows.push(JSON.stringify({ key: `${id}-x${String(i).padStart(2, "0")}`, game: id, todo: true, cls: "standard", category: "unsafe", prompt: "TODO", checks: [], must_refuse: true, adversarial: true }));
  return rows.join("\n") + "\n";
}

function record(id: string, name: string, docsOnly: boolean, date: string): OnboardingRecord {
  return {
    game: id, name, status: "active", phase: "screening", playbookVersion: PLAYBOOK_VERSION,
    adapterFile: docsOnly ? null : `lib/cyrus/adapters/${id}.ts`,
    supportFile: docsOnly ? null : `lib/cyrus/games/${id}.ts`,
    declaredMaturity: "planned", evidence: {}, emitters: [], gates: {}, research: [], updatedAt: date,
  };
}

const fill = (tpl: string, vars: Record<string, string>) => tpl.replace(/\{\{([A-Z_]+)\}\}/g, (m, k: string) => vars[k] ?? m);

export function scaffoldFiles(opts: ScaffoldOptions): ScaffoldFile[] {
  const id = opts.gameId;
  if (!GAME_ID_RE.test(id)) throw new Error(`game id "${id}" must match ${GAME_ID_RE} (lower-case letters and digits, 2-20)`);
  const name = opts.name?.trim() || titleCase(id);
  if (/["\\\n`$]/.test(name)) throw new Error("name may not contain quotes, backslashes, backticks, $ or newlines");
  const language = opts.language ?? "JSON/data";
  if (!LANGUAGES.includes(language)) throw new Error(`language must be one of ${LANGUAGES.join(", ")} (a new language is a GameSupport contract change, see PLAYBOOK phase 3)`);
  const engine = opts.engine ?? "other";
  if (!ENGINES.includes(engine)) throw new Error(`engine must be one of ${ENGINES.join(", ")}`);
  const root = opts.root ?? path.resolve(__dirname, "..", "..");
  const date = opts.date ?? today();
  const tplDir = path.join(root, "docs", "cyrus", "onboarding", "templates");
  const vars = { GAME_ID: id, GAME_NAME: name, DATE: date, PLAYBOOK_VERSION, LANGUAGE: language, ENGINE: engine, GATES: OWNER_GATES.map((g) => g.id).join(", ") };
  const docDir = `docs/cyrus/onboarding/games/${id}`;
  const files: ScaffoldFile[] = [];
  if (!opts.docsOnly) {
    files.push({ path: `lib/cyrus/adapters/${id}.ts`, content: adapterFile(id, name, language, engine) });
    files.push({ path: `lib/cyrus/games/${id}.ts`, content: supportFile(id, name, language) });
    files.push({ path: `lib/cyrus/games/${id}.knowledge.ts`, content: knowledgeFile(id, name) });
    files.push({ path: `services/modbuilder/eval/games/${id}.jsonl`, content: evalStub(id) });
  }
  files.push({ path: `${docDir}/record.json`, content: JSON.stringify(record(id, name, !!opts.docsOnly, date), null, 2) + "\n" });
  for (const s of DOC_STUBS) {
    const tp = path.join(tplDir, s.template);
    if (!existsSync(tp)) throw new Error(`missing template ${path.relative(root, tp)}`);
    files.push({ path: `${docDir}/${s.out}`, content: fill(readFileSync(tp, "utf8"), vars) });
  }
  return files;
}

export function scaffoldGame(opts: ScaffoldOptions): ScaffoldReport {
  const root = opts.root ?? path.resolve(__dirname, "..", "..");
  const report: ScaffoldReport = { gameId: opts.gameId, created: [], kept: [], dryRun: !!opts.dryRun };
  for (const f of scaffoldFiles({ ...opts, root })) {
    const abs = path.join(root, f.path);
    if (existsSync(abs)) { report.kept.push(f.path); continue; }
    report.created.push(f.path);
    if (opts.dryRun) continue;
    mkdirSync(path.dirname(abs), { recursive: true });
    writeFileSync(abs, f.content, { flag: "wx" });
  }
  return report;
}

function parseArgs(argv: string[]): ScaffoldOptions {
  const o: ScaffoldOptions = { gameId: "" };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    const val = () => { const v = argv[++i]; if (v === undefined) throw new Error(`${a} needs a value`); return v; };
    if (a === "--name") o.name = val();
    else if (a === "--language") o.language = val() as ScaffoldOptions["language"];
    else if (a === "--engine") o.engine = val() as ScaffoldOptions["engine"];
    else if (a === "--root") o.root = path.resolve(val());
    else if (a === "--docs-only") o.docsOnly = true;
    else if (a === "--dry-run") o.dryRun = true;
    else if (a.startsWith("--")) throw new Error(`unknown option ${a}`);
    else if (!o.gameId) o.gameId = a;
    else throw new Error(`unexpected argument ${a}`);
  }
  if (!o.gameId) throw new Error("usage: new-game.ts <gameId> [--name N] [--language L] [--engine E] [--docs-only] [--dry-run] [--root DIR]");
  return o;
}

if (require.main === module) {
  try {
    const r = scaffoldGame(parseArgs(process.argv.slice(2)));
    console.log(JSON.stringify(r, null, 2));
    console.log(`\nNext: open docs/cyrus/onboarding/games/${r.gameId}/TODO.md and start phase 0 (SCORECARD.md). Nothing was registered or switched on.`);
  } catch (e) {
    console.error(`new-game: ${(e as Error).message}`);
    process.exit(1);
  }
}

