// Cyrus game onboarding kit (r47): the maturity ladder, onboarding health over every game record, the derived capability
// manifest, the checklist parser, the docs coverage of the playbook, and the scaffolder end to end (generate a fake
// game, regenerate = no change, type-check the generated files, host seam, adapter + profile validation, clean up).
// Pure apart from the scaffolder test, which writes into the repo and removes everything it wrote (try/finally).
// Run: tsx --test test/cyrus-onboarding.test.ts
import { after, describe, it } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync, readdirSync, rmSync, statSync } from "node:fs";
import path from "node:path";
import ts from "typescript";
import { ADAPTERS } from "../lib/cyrus/adapters";
import { minecraftAdapter } from "../lib/cyrus/adapters/minecraft";
import { validateAssetProfile } from "../lib/cyrus/adapters/asset-profile";
import { checkRecord, errorsOf, evidenceMaturity, LADDER_CRITERIA } from "../lib/cyrus/onboarding/health";
import { capabilityManifest, studioRows } from "../lib/cyrus/onboarding/manifest";
import { parseTodo } from "../lib/cyrus/onboarding/todo";
import { MATURITY_LADDER, OWNER_GATES, PHASES, PLAYBOOK_VERSION, STUDIO_IDS, type OnboardingRecord } from "../lib/cyrus/onboarding/types";
import { listOnboardingIds, loadOnboarding } from "../lib/cyrus/onboarding/records.server";
import { DOC_STUBS, EVAL_SLOTS, loadAdapterModule, scaffoldFiles, scaffoldGame } from "../scripts/cyrus/new-game";

const ROOT = path.resolve(__dirname, "..");
const KIT = path.join(ROOT, "docs", "cyrus", "onboarding");
const read = (p: string) => readFileSync(path.join(ROOT, p), "utf8");
const DAY = "2026-10-11";

const base = (over: Partial<OnboardingRecord> = {}): OnboardingRecord => ({
  game: "zzexample", name: "Example", status: "active", phase: "screening", playbookVersion: PLAYBOOK_VERSION, adapterFile: null, supportFile: null,
  declaredMaturity: "planned", evidence: {}, emitters: [], gates: {}, research: ["x.md"], updatedAt: DAY, ...over,
});
const codes = (r: OnboardingRecord, m?: Parameters<typeof checkRecord>[1]) => errorsOf(checkRecord(r, m)).map((i) => i.code);
const ev = (passed: number, total: number) => ({ ref: "r.json", at: DAY, passed, total });
const sig = { by: "owner", at: DAY };

describe("onboarding: maturity ladder", () => {
  it("evidence decides the rung, never the claim", () => {
    assert.equal(evidenceMaturity({}), "planned");
    const t = { templateValidated: { ref: "t", at: DAY } };
    assert.equal(evidenceMaturity(t), "template");
    const beta = { ...t, compile: ev(19, 20), scan: { ref: "s", at: DAY }, eval: ev(16, 20) };
    assert.equal(evidenceMaturity(beta), "beta");
    assert.equal(evidenceMaturity({ ...beta, compile: ev(17, 20) }), "template", "compile under 90%");
    assert.equal(evidenceMaturity({ ...beta, eval: ev(10, 10) }), "template", "eval sample under 20");
    assert.equal(evidenceMaturity({ ...beta, scan: undefined }), "template", "no scan");
    const stable = { ...beta, flight: ev(10, 10), realClientDay: { ref: "d", at: DAY }, legalReviewed: { ref: "l", at: DAY } };
    assert.equal(evidenceMaturity(stable), "stable");
    assert.equal(evidenceMaturity({ ...stable, flight: ev(9, 9) }), "beta", "flights under the 10 floor");
    assert.equal(evidenceMaturity({ ...stable, realClientDay: undefined }), "beta");
    assert.equal(evidenceMaturity({ ...stable, flight: { ...ev(11, 10) } }), "beta", "passed > total is not evidence");
  });
  it("a record may not claim more than its evidence, nor an adapter more than its record", () => {
    assert.deepEqual(codes(base()), []);
    assert.ok(codes(base({ declaredMaturity: "template" })).includes("maturity_exceeds_evidence"));
    assert.ok(codes(base(), "beta").includes("adapter_exceeds_record"));
    assert.ok(codes(base({ adapterFile: "lib/cyrus/adapters/zzexample.ts" }), null).includes("adapter_not_loaded"));
    assert.deepEqual(codes(base({ adapterFile: "lib/cyrus/adapters/zzexample.ts" }), "planned"), []);
  });
  it("owner gates: beta needs G6, stable G7, past screening G0, live G9; grandfathered games only warn", () => {
    const betaEv = { templateValidated: { ref: "t", at: DAY }, compile: ev(20, 20), scan: { ref: "s", at: DAY }, eval: ev(20, 20) };
    const b = base({ declaredMaturity: "beta", evidence: betaEv, phase: "verification" });
    assert.deepEqual(codes(b).sort(), ["beta_gate", "go_gate"]);
    assert.deepEqual(codes({ ...b, gates: { "G0-go": sig, "G6-beta": sig } }), []);
    assert.deepEqual(codes({ ...b, retrofit: true }), [], "retro-fitted: warnings only");
    assert.ok(checkRecord({ ...b, retrofit: true }).some((i) => i.code === "beta_gate" && i.severity === "warn"));
    assert.ok(codes({ ...b, status: "live", gates: { "G0-go": sig, "G6-beta": sig } }).includes("live_gate"));
    assert.ok(codes(base({ status: "on-hold" })).includes("hold_reason"));
    assert.ok(codes(base({ gates: { "G6-beta": { by: "", at: DAY } } })).includes("bad_signature"), "an empty signature is not a signature");
  });
  it("the playbook's ladder table and gate list match the code", () => {
    const pb = readFileSync(path.join(KIT, "PLAYBOOK.md"), "utf8");
    for (const m of MATURITY_LADDER) assert.ok(pb.includes(LADDER_CRITERIA[m].summary), `PLAYBOOK.md prints the ${m} criteria verbatim`);
    for (const g of OWNER_GATES) assert.ok(pb.includes(g.id), `PLAYBOOK.md names gate ${g.id}`);
    for (const p of PHASES) assert.match(pb, new RegExp(`## Phase ${p.n}\\b`), `PLAYBOOK.md has a section for phase ${p.n}`);
  });
});

describe("onboarding: capability manifest", () => {
  it("Minecraft: emitters + delivery decide; nothing is usable on a planned adapter", () => {
    const rows = new Map(studioRows(minecraftAdapter, STUDIO_IDS).map((r) => [r.id, r]));
    assert.equal(rows.get("designers")!.state, "usable");
    assert.equal(rows.get("motion-studio")!.state, "usable");
    // texture/sound delivery are declared "planned" in the Minecraft adapter (pack delivery is behind flags), so the studios are planned
    assert.equal(rows.get("texture-studio")!.state, "planned");
    assert.match(rows.get("texture-studio")!.reason, /texture delivery is planned/);
    assert.equal(rows.get("datapack-studio")!.state, "planned");
    const none = new Map(studioRows(minecraftAdapter, []).map((r) => [r.id, r]));
    assert.ok([...none.values()].every((r) => r.state !== "usable"), "no emitters = nothing usable");
    assert.ok(studioRows(null, STUDIO_IDS).every((r) => r.state === "hidden"));
  });
  it("legal classes: game-derived only where the game needs game files, and always job-only", () => {
    const m = capabilityManifest(minecraftAdapter, { game: "minecraft", emitters: [], declaredMaturity: "beta" });
    assert.ok(m.legal.every((r) => !r.allowed.some((a) => a.cls === "game-derived")), "Minecraft needs no game files");
    const p = { ...minecraftAdapter.assetProfile!, requiredGameFiles: "user-supplied" as const };
    const m2 = capabilityManifest({ ...minecraftAdapter, assetProfile: p }, { game: "minecraft", emitters: [], declaredMaturity: "beta" });
    const gd = m2.legal[0].allowed.find((a) => a.cls === "game-derived")!;
    assert.deepEqual([gd.storage, gd.library], ["job-only", false]);
    assert.deepEqual(m.workerClasses, ["linux-cpu"]);
  });
});

describe("onboarding: checklist parser", () => {
  it("reads phases, ticks and open owner gates", () => {
    const t = parseTodo("# X\n## P0 Screening\n- [x] a\n- [ ] OWNER GATE G0-go: yes\n## P1 Research\n- [ ] b\n## Notes\n- [ ] not counted\n");
    assert.deepEqual([t.done, t.total, t.currentPhase], [1, 3, 0]);
    assert.deepEqual(t.gatesOpen, ["G0-go"]);
    assert.equal(t.phases[0].items[1].gate, "G0-go");
  });
  it("the TODO template has ten phases and every owner gate", () => {
    const t = parseTodo(readFileSync(path.join(KIT, "templates", "TODO.md"), "utf8"));
    assert.deepEqual(t.phases.map((p) => p.n), PHASES.map((p) => p.n));
    assert.deepEqual([...t.gatesOpen].sort(), OWNER_GATES.map((g) => g.id).sort());
  });
});

describe("onboarding health: every game record", () => {
  it("every registered adapter has an onboarding record", async () => {
    const ids = await listOnboardingIds(ROOT);
    for (const a of ADAPTERS) assert.ok(ids.includes(a.game), `docs/cyrus/onboarding/games/${a.game}/record.json missing`);
  });
  it("no record claims more than its evidence (adapters loaded from their files)", async () => {
    const ids = await listOnboardingIds(ROOT);
    assert.ok(ids.length >= 6, "minecraft, terraria, valheim, zomboid, hytale, fivem");
    for (const id of ids) {
      const rec = JSON.parse(read(`docs/cyrus/onboarding/games/${id}/record.json`)) as OnboardingRecord;
      assert.equal(rec.game, id);
      let maturity: (typeof MATURITY_LADDER)[number] | null | undefined;
      if (rec.adapterFile) {
        const a = existsSync(path.join(ROOT, rec.adapterFile)) ? await loadAdapterModule(path.join(ROOT, rec.adapterFile)) : null;
        maturity = a ? a.maturity : null;
        if (a?.assetProfile) assert.deepEqual(validateAssetProfile(a.assetProfile), [], `${id} asset profile`);
      }
      if (rec.supportFile) assert.ok(existsSync(path.join(ROOT, rec.supportFile)), `${id}: ${rec.supportFile}`);
      assert.deepEqual(errorsOf(checkRecord(rec, maturity)), [], `${id} onboarding health`);
      assert.ok(existsSync(path.join(KIT, "games", id, "TODO.md")), `${id} TODO.md`);
      for (const r of rec.research) if (!r.startsWith("/")) assert.ok(existsSync(path.join(ROOT, r)), `${id} research ${r}`);
    }
  });
  it("the server loader returns the view the admin page shows", async () => {
    const v = (await loadOnboarding("minecraft", { root: ROOT }))!;
    assert.equal(v.registered, true);
    assert.equal(v.proven, "beta");
    assert.ok(v.todo && v.todo.total > 40 && v.todo.done > 0);
    assert.deepEqual(errorsOf(v.issues), []);
    assert.equal(await loadOnboarding("../etc", { root: ROOT }), null);
  });
});

describe("onboarding docs coverage", () => {
  it("playbook version is the same in code, PLAYBOOK.md and the top CHANGELOG entry", () => {
    assert.match(readFileSync(path.join(KIT, "PLAYBOOK.md"), "utf8"), new RegExp(`Playbook version: \\*\\*${PLAYBOOK_VERSION.replace(/\./g, "\\.")}\\*\\*`));
    const top = /^## (\d+\.\d+\.\d+)/m.exec(readFileSync(path.join(KIT, "CHANGELOG.md"), "utf8"));
    assert.equal(top?.[1], PLAYBOOK_VERSION);
  });
  it("the kit files exist and the playbook links them", () => {
    const pb = readFileSync(path.join(KIT, "PLAYBOOK.md"), "utf8");
    for (const f of ["README.md", "PLAYBOOK.md", "CASE-STUDIES.md", "IMPROVEMENTS.md", "LESSONS.md", "CHANGELOG.md"]) assert.ok(existsSync(path.join(KIT, f)), f);
    for (const s of DOC_STUBS) {
      assert.ok(existsSync(path.join(KIT, "templates", s.template)), s.template);
      assert.ok(pb.includes(`templates/${s.template}`), `PLAYBOOK.md links templates/${s.template}`);
    }
    for (const b of ["COMMON-RULES.md", "SCREENING.md", "RESEARCH.md", "BUILD.md", "REVIEW.md"]) assert.ok(pb.includes(`agent-briefs/${b}`) && existsSync(path.join(KIT, "templates", "agent-briefs", b)), b);
  });
  it("the lessons log has the required shape and at least one entry", () => {
    const l = readFileSync(path.join(KIT, "LESSONS.md"), "utf8");
    const entries = l.match(/^### L\d+ /gm) ?? [];
    assert.ok(entries.length >= 1);
    assert.ok(/Rule:/.test(l) && /Playbook change:/.test(l));
  });
});

describe("scaffolder: scripts/cyrus/new-game.ts", () => {
  const ID = "zzonboardtest";
  const written: string[] = [];
  const cleanup = () => {
    for (const f of written) rmSync(path.join(ROOT, f), { force: true });
    rmSync(path.join(KIT, "games", ID), { recursive: true, force: true });
    const evalDir = path.join(ROOT, "services", "modbuilder", "eval", "games");
    if (existsSync(evalDir) && readdirSync(evalDir).length === 0) rmSync(evalDir, { recursive: true, force: true });
  };
  after(cleanup);

  it("rejects bad ids and names before touching disk", () => {
    assert.throws(() => scaffoldFiles({ gameId: "Bad-Id", root: ROOT }), /must match/);
    assert.throws(() => scaffoldFiles({ gameId: "../x", root: ROOT }), /must match/);
    assert.throws(() => scaffoldFiles({ gameId: "zzok", name: 'a"b', root: ROOT }), /may not contain/);
    assert.throws(() => scaffoldFiles({ gameId: "zzok", language: "Rust" as never, root: ROOT }), /language must be/);
  });

  it("generates the skeleton once, idempotently, and it passes tsc, the seam rule, the profile and health checks", async () => {
    cleanup();
    try {
      const first = scaffoldGame({ gameId: ID, name: "Onboard Test", language: "Lua", engine: "other", root: ROOT, date: DAY });
      written.push(...first.created);
      assert.equal(first.kept.length, 0);
      assert.equal(first.created.length, 4 + 1 + DOC_STUBS.length);
      const second = scaffoldGame({ gameId: ID, name: "Onboard Test", language: "Lua", root: ROOT, date: DAY });
      assert.deepEqual(second.created, [], "second run writes nothing");
      assert.deepEqual(second.kept.sort(), [...first.created].sort());

      const tsFiles = first.created.filter((f) => f.endsWith(".ts"));
      assert.deepEqual(tsFiles.sort(), [`lib/cyrus/adapters/${ID}.ts`, `lib/cyrus/games/${ID}.knowledge.ts`, `lib/cyrus/games/${ID}.ts`]);
      // HOST SEAM: generated code imports only inside lib/cyrus
      for (const f of tsFiles) for (const m of read(f).matchAll(/from\s+"([^"]+)"/g)) {
        const t = path.relative(ROOT, path.resolve(path.dirname(path.join(ROOT, f)), m[1])).split(path.sep).join("/");
        assert.ok(t.startsWith("lib/cyrus/"), `${f} imports ${m[1]} (outside lib/cyrus)`);
      }
      // type-check the generated files with the repo's own compiler options
      const cfg = ts.parseJsonConfigFileContent(ts.readConfigFile(path.join(ROOT, "tsconfig.json"), ts.sys.readFile).config, ts.sys, ROOT);
      const program = ts.createProgram(tsFiles.map((f) => path.join(ROOT, f)), { ...cfg.options, noEmit: true, incremental: false });
      const diags = ts.getPreEmitDiagnostics(program).filter((d) => d.file && tsFiles.some((f) => d.file!.fileName.endsWith(f)));
      assert.deepEqual(diags.map((d) => `${d.file!.fileName}: ${ts.flattenDiagnosticMessageText(d.messageText, "\n")}`), []);

      const adapter = (await loadAdapterModule(path.join(ROOT, `lib/cyrus/adapters/${ID}.ts`)))!;
      assert.equal(adapter.game, ID);
      assert.equal(adapter.maturity, "planned");
      assert.deepEqual(validateAssetProfile(adapter.assetProfile!), []);
      assert.equal(adapter.assetProfile!.legal.reviewed, false);
      assert.ok(!ADAPTERS.some((a) => a.game === ID), "the scaffolder registers nothing");
      const support = ((await import(path.join(ROOT, `lib/cyrus/games/${ID}.ts`))) as { default: { default?: unknown } }).default;
      const gs = ((support as { default?: unknown }).default ?? support) as { id: string; unknowns: string[]; language: string };
      assert.deepEqual([gs.id, gs.language], [ID, "Lua"]);
      assert.ok(gs.unknowns.length >= 5);

      const rec = JSON.parse(read(`docs/cyrus/onboarding/games/${ID}/record.json`)) as OnboardingRecord;
      assert.deepEqual([rec.phase, rec.declaredMaturity, rec.status, rec.updatedAt], ["screening", "planned", "active", DAY]);
      assert.deepEqual(errorsOf(checkRecord(rec, adapter.maturity)), []);
      const man = capabilityManifest(adapter, rec);
      assert.ok(man.studios.every((s) => s.state !== "usable"), "flag nothing on: no studio is usable");
      const todo = parseTodo(read(`docs/cyrus/onboarding/games/${ID}/TODO.md`));
      assert.deepEqual([todo.done, todo.phases.length, todo.gatesOpen.length], [0, PHASES.length, OWNER_GATES.length]);
      assert.ok(!read(`docs/cyrus/onboarding/games/${ID}/SCORECARD.md`).includes("{{"), "placeholders filled");
      const evalRows = read(`services/modbuilder/eval/games/${ID}.jsonl`).trim().split("\n").map((l) => JSON.parse(l));
      assert.equal(evalRows.length, EVAL_SLOTS.prompts + EVAL_SLOTS.adversarial);
      assert.equal(evalRows.filter((r) => r.must_refuse).length, EVAL_SLOTS.adversarial);
      assert.ok(evalRows.every((r) => r.todo === true && r.game === ID));
    } finally {
      cleanup();
    }
    for (const f of written) assert.ok(!existsSync(path.join(ROOT, f)), `cleaned ${f}`);
    assert.ok(!existsSync(path.join(KIT, "games", ID)));
  });

  it("--docs-only writes only the onboarding folder", () => {
    const files = scaffoldFiles({ gameId: ID, docsOnly: true, root: ROOT, date: DAY });
    assert.ok(files.every((f) => f.path.startsWith(`docs/cyrus/onboarding/games/${ID}/`)));
    const rec = JSON.parse(files.find((f) => f.path.endsWith("record.json"))!.content) as OnboardingRecord;
    assert.deepEqual([rec.adapterFile, rec.supportFile], [null, null]);
    assert.ok(statSync(path.join(KIT, "templates")).isDirectory());
  });
});

