              {views.map(({ record: r, todo, issues, proven, manifest, registered }) => {
                const usable = manifest.studios.filter((s) => s.state === "usable").length;
                const planned = manifest.studios.filter((s) => s.state === "planned").length;
                const errors = issues.filter((i) => i.severity === "error");
                const warns = issues.filter((i) => i.severity === "warn");
                return (
                  <tr key={r.game} className={tdRow}>
                    <td className="whitespace-nowrap font-medium">{r.name}<div className="font-mono text-xs text-slate-500">{r.game}{registered ? " · adapter registered" : r.adapterFile ? " · adapter not registered" : " · no adapter"}</div></td>
                    <td><Badge tone={statusTone(r.status)}>{r.status}</Badge>{r.holdReason ? <div className="mt-1 max-w-[220px] text-xs text-slate-500">{r.holdReason}</div> : null}</td>
                    <td className="whitespace-nowrap text-xs">{phaseLabel(r.phase)}</td>
                    <td className="whitespace-nowrap text-xs">{r.declaredMaturity} / {proven}</td>
                    <td className="whitespace-nowrap text-xs">{todo ? `${todo.done} / ${todo.total}` : <span className="text-slate-500">no TODO.md</span>}</td>
                    <td className="max-w-[200px] text-xs">{todo?.gatesOpen.length ? todo.gatesOpen.join(", ") : <span className="text-slate-500">none</span>}</td>
                    <td className="whitespace-nowrap text-xs" title={manifest.studios.map((s) => `${s.name}: ${s.state} (${s.reason})`).join("\n")}>{usable} usable · {planned} planned</td>
                    <td className="max-w-[260px] text-xs">{errors.length ? <Badge tone="red">{errors.length} error(s)</Badge> : <Badge tone="green">ok</Badge>}{[...errors, ...warns].slice(0, 3).map((i) => <div key={i.code} className={i.severity === "error" ? "text-red-400" : "text-slate-500"}>{i.message}</div>)}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </TableWrap>
      )}
      <p className="mt-2 text-xs text-slate-500">Proven = the highest rung the recorded evidence supports (lib/cyrus/onboarding/health.ts). The onboarding health test fails a record that declares more. Hover a studio count for the per-studio reasons.</p>
    </Section>
  );
}

