  const ID = "zzonboardtest";
  // The scaffolder writes into a TEMPORARY MIRROR of the repo, never into the repo itself: other suites walk lib/cyrus
  // (host seam ratchet, the docs generator, the games list) in parallel and must never see a half-written fake game.
  // The mirror is real directories for lib/cyrus/adapters + lib/cyrus/games (so new files land in the mirror) holding
  // symlinks to the real files, and symlinks for everything else; TypeScript and Node resolve symlinks to the real
  // files, so the generated code is type-checked and loaded against the real contract.
  const tmp = mkdtempSync(path.join(os.tmpdir(), "cyrus-onboard-"));
  const mirror = () => {
    const link = (rel: string) => symlinkSync(path.join(ROOT, rel), path.join(tmp, rel));
    mkdirSync(path.join(tmp, "lib", "cyrus"), { recursive: true });
    for (const n of readdirSync(path.join(ROOT, "lib", "cyrus"))) {
      if (n === "adapters" || n === "games") {
        mkdirSync(path.join(tmp, "lib", "cyrus", n));
        for (const f of readdirSync(path.join(ROOT, "lib", "cyrus", n))) link(`lib/cyrus/${n}/${f}`);
      } else link(`lib/cyrus/${n}`);
    }
    for (const n of readdirSync(path.join(ROOT, "lib"))) if (n !== "cyrus") link(`lib/${n}`);
    for (const n of ["node_modules", "tsconfig.json", "package.json", "services", "next-env.d.ts"]) if (existsSync(path.join(ROOT, n))) link(n);
    mkdirSync(path.join(tmp, "docs", "cyrus", "onboarding"), { recursive: true });
    link("docs/cyrus/onboarding/templates");
  };
  after(() => {
    rmSync(tmp, { recursive: true, force: true }); // removes the links, never their targets
    assert.ok(existsSync(path.join(ROOT, "lib", "cyrus", "adapters", "minecraft.ts")), "real files untouched");
  });

  it("rejects bad ids and names before touching disk", () => {
    assert.throws(() => scaffoldFiles({ gameId: "Bad-Id", root: ROOT }), /must match/);
    assert.throws(() => scaffoldFiles({ gameId: "../x", root: ROOT }), /must match/);
    assert.throws(() => scaffoldFiles({ gameId: "zzok", name: 'a"b', root: ROOT }), /may not contain/);
    assert.throws(() => scaffoldFiles({ gameId: "zzok", language: "Rust" as never, root: ROOT }), /language must be/);
  });

  it("generates the skeleton once, idempotently, and it passes tsc, the seam rule, the profile and health checks", async () => {
    mirror();
    const at = (rel: string) => path.join(tmp, rel);
    const first = scaffoldGame({ gameId: ID, name: "Onboard Test", language: "Lua", engine: "other", root: tmp, date: DAY });
    assert.equal(first.kept.length, 0);
    assert.equal(first.created.length, 4 + 1 + DOC_STUBS.length);
    for (const f of first.created) assert.ok(!lstatSync(at(f)).isSymbolicLink() && !existsSync(path.join(ROOT, f)), `${f} written to the mirror only`);
    const second = scaffoldGame({ gameId: ID, name: "Onboard Test", language: "Lua", root: tmp, date: DAY });
    assert.deepEqual(second.created, [], "second run writes nothing");
    assert.deepEqual(second.kept.sort(), [...first.created].sort());

    const tsFiles = first.created.filter((f) => f.endsWith(".ts"));
    assert.deepEqual(tsFiles.sort(), [`lib/cyrus/adapters/${ID}.ts`, `lib/cyrus/games/${ID}.knowledge.ts`, `lib/cyrus/games/${ID}.ts`]);
    // HOST SEAM: generated code imports only inside lib/cyrus
    for (const f of tsFiles) for (const m of readFileSync(at(f), "utf8").matchAll(/from\\s+"([^"]+)"/g)) {
      const t = path.relative(tmp, path.resolve(path.dirname(at(f)), m[1])).split(path.sep).join("/");
      assert.ok(t.startsWith("lib/cyrus/"), `${f} imports ${m[1]} (outside lib/cyrus)`);
    }
    // type-check the generated files with the repo's own compiler options
    const cfg = ts.parseJsonConfigFileContent(ts.readConfigFile(path.join(ROOT, "tsconfig.json"), ts.sys.readFile).config, ts.sys, ROOT);
    const program = ts.createProgram(tsFiles.map(at), { ...cfg.options, noEmit: true, incremental: false });
    const mine = (d: ts.Diagnostic) => !!d.file && tsFiles.some((f) => d.file!.fileName.endsWith(f));
    const all = ts.getPreEmitDiagnostics(program);
    assert.ok(program.getSourceFiles().some((sf) => sf.fileName.endsWith("lib/cyrus/adapters/types.ts")), "the real contract was loaded");
    assert.deepEqual(all.filter(mine).map((d) => `${d.file!.fileName}: ${ts.flattenDiagnosticMessageText(d.messageText, "\\n")}`), []);

    const adapter = (await loadAdapterModule(at(`lib/cyrus/adapters/${ID}.ts`)))!;
    assert.equal(adapter.game, ID);
    assert.equal(adapter.maturity, "planned");
    assert.deepEqual(validateAssetProfile(adapter.assetProfile!), []);
    assert.equal(adapter.assetProfile!.legal.reviewed, false);
    assert.ok(!ADAPTERS.some((a) => a.game === ID), "the scaffolder registers nothing");
    const support = ((await import(at(`lib/cyrus/games/${ID}.ts`))) as { default: { default?: unknown } }).default;
    const gs = ((support as { default?: unknown }).default ?? support) as { id: string; unknowns: string[]; language: string };
    assert.deepEqual([gs.id, gs.language], [ID, "Lua"]);
    assert.ok(gs.unknowns.length >= 5);

    const rec = JSON.parse(readFileSync(at(`docs/cyrus/onboarding/games/${ID}/record.json`), "utf8")) as OnboardingRecord;
    assert.deepEqual([rec.phase, rec.declaredMaturity, rec.status, rec.updatedAt], ["screening", "planned", "active", DAY]);
    assert.deepEqual(errorsOf(checkRecord(rec, adapter.maturity)), []);
    const man = capabilityManifest(adapter, rec);
    assert.ok(man.studios.every((s) => s.state !== "usable"), "flag nothing on: no studio is usable");
    assert.deepEqual((await derivedManifest(ID, tmp)).studios, man.studios, "--manifest prints the same derivation");
    const todo = parseTodo(readFileSync(at(`docs/cyrus/onboarding/games/${ID}/TODO.md`), "utf8"));
    assert.deepEqual([todo.done, todo.phases.length, todo.gatesOpen.length], [0, PHASES.length, OWNER_GATES.length]);
    assert.ok(!readFileSync(at(`docs/cyrus/onboarding/games/${ID}/SCORECARD.md`), "utf8").includes("{{"), "placeholders filled");
    const evalRows = readFileSync(at(`services/modbuilder/eval/games/${ID}.jsonl`), "utf8").trim().split("\\n").map((l) => JSON.parse(l));
    assert.equal(evalRows.length, EVAL_SLOTS.prompts + EVAL_SLOTS.adversarial);
    assert.equal(evalRows.filter((r) => r.must_refuse).length, EVAL_SLOTS.adversarial);
    assert.ok(evalRows.every((r) => r.todo === true && r.game === ID));
  });

  it("--docs-only writes only the onboarding folder", () => {
    const files = scaffoldFiles({ gameId: ID, docsOnly: true, root: ROOT, date: DAY });
    assert.ok(files.every((f) => f.path.startsWith(`docs/cyrus/onboarding/games/${ID}/`)));
    const rec = JSON.parse(files.find((f) => f.path.endsWith("record.json"))!.content) as OnboardingRecord;
    assert.deepEqual([rec.adapterFile, rec.supportFile], [null, null]);
    assert.ok(statSync(path.join(KIT, "templates")).isDirectory());
  });
});
'''
