s=s.replace('import { DOC_STUBS, EVAL_SLOTS, loadAdapterModule, scaffoldFiles, scaffoldGame } from "../scripts/cyrus/new-game";','import { DOC_STUBS, EVAL_SLOTS, derivedManifest, loadAdapterModule, scaffoldFiles, scaffoldGame } from "../scripts/cyrus/new-game";')
s=s.replace("// Pure apart from the scaffolder test, which writes into the repo and removes everything it wrote (try/finally).","// Pure apart from the scaffolder test, which writes into a temporary mirror of the repo (never the repo) and deletes it.")
open(p,'w').write(s)
